import React, { useState } from 'react';
import './WelcomeModal.css';

const WelcomeModal = ({ isOpen, onClose }) => {
  const [prompt, setPrompt] = useState('');

  if (!isOpen) return null;

  return (
    <div className="modal-overlay">
      <div className="modal-content">
        <div className="modal-header">
          <h1>Unveiling the Power of Test Case Generation and Execution</h1>
          <p className="subtitle">Software testing redefined through AI-driven automation and meticulous scrutiny, ensuring precision</p>
        </div>

        <div className="modal-body">
          <h2>Start</h2>
          <p className="welcome-text">
            Welcome to Agent QA! You can start your journey with QA Agent now to get your GUI & API testing done!
          </p>

          <div className="prompt-section">
            <div className="prompt-box">
              <label>Enter your prompt</label>
              <input 
                type="text" 
                placeholder="To start new chat for generating test cases"
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
              />
            </div>
            <button className="next-button">
              Next <span className="arrow">→</span>
            </button>
          </div>
        </div>

        <button className="modal-close" onClick={onClose}>×</button>
      </div>
    </div>
  );
};

export default WelcomeModal;
